insert into public.categories (id, icon, application_ids, title, blurb, consider, sort_order) values
  ('smart-farming', 'sprout', array['farm-planning','crop-monitoring']::text[], $j${"en":"Smart Farming","sw":"Kilimo Janja"}$j$::jsonb, $j${"en":"Connected sensors, controllers and data tools that help run a farm with fewer guesses.","sw":"Vitambuzi, vidhibiti na zana za data zinazosaidia kuendesha shamba kwa makadirio machache."}$j$::jsonb, $j${"en":"Start with one measurement that matters, such as rainfall or soil moisture, before adding more devices.","sw":"Anza na kipimo kimoja muhimu, kama mvua au unyevu wa udongo, kabla ya kuongeza vifaa zaidi."}$j$::jsonb, 0),
  ('precision-agriculture', 'target', array['soil-fertility','crop-monitoring']::text[], $j${"en":"Precision Agriculture","sw":"Kilimo Sahihi"}$j$::jsonb, $j${"en":"Methods that apply seed, water and nutrients where and when each part of a field needs them.","sw":"Mbinu zinazotumia mbegu, maji na virutubisho mahali na wakati kila sehemu ya shamba inapohitaji."}$j$::jsonb, $j${"en":"Good field maps and records matter as much as the equipment itself.","sw":"Ramani nzuri za shamba na kumbukumbu ni muhimu kama vifaa vyenyewe."}$j$::jsonb, 1),
  ('ai-in-agriculture', 'chip', array['pest-disease','crop-monitoring']::text[], $j${"en":"Artificial Intelligence in Agriculture","sw":"Akili Bandia katika Kilimo"}$j$::jsonb, $j${"en":"Models that read images and data to flag pests, forecast yields and support decisions.","sw":"Mifumo inayosoma picha na data kutambua wadudu, kukadiria mavuno na kusaidia maamuzi."}$j$::jsonb, $j${"en":"Treat suggestions as a first opinion and confirm important decisions with an adviser.","sw":"Chukulia mapendekezo kama maoni ya kwanza na thibitisha maamuzi muhimu na mshauri."}$j$::jsonb, 2),
  ('agricultural-drones', 'drone', array['crop-monitoring','pest-disease']::text[], $j${"en":"Agricultural Drones","sw":"Ndege zisizo na Rubani za Kilimo"}$j$::jsonb, $j${"en":"Aerial platforms for scouting fields, mapping and targeted spraying.","sw":"Majukwaa ya angani ya kukagua mashamba, kuchora ramani na kunyunyizia kwa lengo."}$j$::jsonb, $j${"en":"Check local flight rules and operator requirements before buying or hiring.","sw":"Angalia kanuni za ndege za eneo na mahitaji ya waendeshaji kabla ya kununua au kukodi."}$j$::jsonb, 3),
  ('smart-irrigation', 'droplet', array['water-saving','energy-access']::text[], $j${"en":"Smart Irrigation","sw":"Umwagiliaji Janja"}$j$::jsonb, $j${"en":"Systems that deliver water in the right amount at the right time, often with solar power.","sw":"Mifumo inayotoa maji kwa kiasi sahihi wakati sahihi, mara nyingi kwa nguvu ya jua."}$j$::jsonb, $j${"en":"Water quality affects blockages, so ask about filters and cleaning.","sw":"Ubora wa maji huathiri kuziba, kwa hiyo uliza kuhusu vichujio na usafishaji."}$j$::jsonb, 4),
  ('soil-health', 'layers', array['soil-fertility']::text[], $j${"en":"Soil Health Technology","sw":"Teknolojia ya Afya ya Udongo"}$j$::jsonb, $j${"en":"Tools for testing soil and guiding fertilizer, cover and rotation choices.","sw":"Zana za kupima udongo na kuongoza uchaguzi wa mbolea, kifuniko na mzunguko wa mazao."}$j$::jsonb, $j${"en":"Take samples the same way each time so results can be compared across seasons.","sw":"Chukua sampuli kwa njia ileile kila mara ili matokeo yalinganishwe katika misimu."}$j$::jsonb, 5),
  ('agricultural-robotics', 'robot', array['mechanization','herd-health']::text[], $j${"en":"Agricultural Robotics","sw":"Roboti za Kilimo"}$j$::jsonb, $j${"en":"Machines that take on repetitive field and dairy tasks such as weeding and milking.","sw":"Mashine zinazofanya kazi za kurudia-rudia shambani na kwenye maziwa kama palizi na kukamua."}$j$::jsonb, $j${"en":"Robots need reliable power, trained operators and nearby technical support.","sw":"Roboti zinahitaji umeme wa uhakika, waendeshaji waliofunzwa na msaada wa kiufundi karibu."}$j$::jsonb, 6),
  ('greenhouse', 'greenhouse', array['climate-control','water-saving']::text[], $j${"en":"Greenhouse Technology","sw":"Teknolojia ya Nyumba Kitalu"}$j$::jsonb, $j${"en":"Structures and controls that keep heat, humidity and light steady for crops.","sw":"Miundo na vidhibiti vinavyoweka joto, unyevu na mwanga thabiti kwa mazao."}$j$::jsonb, $j${"en":"Ventilation and disease control matter as much as the structure itself.","sw":"Uingizaji hewa na udhibiti wa magonjwa ni muhimu kama muundo wenyewe."}$j$::jsonb, 7),
  ('crop-protection', 'shield', array['pest-disease']::text[], $j${"en":"Crop Protection","sw":"Ulinzi wa Mazao"}$j$::jsonb, $j${"en":"Approaches for watching and reducing pest, disease and weed pressure.","sw":"Mbinu za kufuatilia na kupunguza shinikizo la wadudu, magonjwa na magugu."}$j$::jsonb, $j${"en":"Follow product labels and local advice, and keep spray records.","sw":"Fuata maelekezo ya bidhaa na ushauri wa eneo, na uweke kumbukumbu za unyunyiziaji."}$j$::jsonb, 8),
  ('livestock-technology', 'cow', array['herd-health','feed-nutrition','climate-control']::text[], $j${"en":"Livestock Technology","sw":"Teknolojia ya Mifugo"}$j$::jsonb, $j${"en":"Tags, controllers and records that support animal health, feeding and housing.","sw":"Vitambulisho, vidhibiti na kumbukumbu zinazosaidia afya ya wanyama, ulishaji na makazi."}$j$::jsonb, $j${"en":"Technology supports, but does not replace, regular checks by a qualified veterinarian.","sw":"Teknolojia inasaidia, lakini haibadilishi, ukaguzi wa kawaida na daktari wa mifugo aliyehitimu."}$j$::jsonb, 9),
  ('farm-software', 'laptop', array['farm-planning','market-access']::text[], $j${"en":"Farm Management Software","sw":"Programu za Usimamizi wa Shamba"}$j$::jsonb, $j${"en":"Apps and services for records, advice, planning and farm finances.","sw":"Programu na huduma za kumbukumbu, ushauri, mipango na fedha za shamba."}$j$::jsonb, $j${"en":"Check that the tool works offline and in your language before relying on it.","sw":"Hakikisha zana inafanya kazi bila mtandao na kwa lugha yako kabla ya kuitegemea."}$j$::jsonb, 10),
  ('processing', 'factory', array['post-harvest','market-access']::text[], $j${"en":"Agricultural Processing","sw":"Usindikaji wa Mazao ya Kilimo"}$j$::jsonb, $j${"en":"Drying, chilling and processing equipment that adds value and cuts losses.","sw":"Vifaa vya kukausha, kupoza na kusindika vinavyoongeza thamani na kupunguza hasara."}$j$::jsonb, $j${"en":"Hygiene and quality standards for your market affect which equipment you can use.","sw":"Viwango vya usafi na ubora vya soko lako huathiri vifaa unavyoweza kutumia."}$j$::jsonb, 11),
  ('renewable-energy', 'sun', array['energy-access','post-harvest']::text[], $j${"en":"Renewable Energy for Agriculture","sw":"Nishati Mbadala kwa Kilimo"}$j$::jsonb, $j${"en":"Solar and other clean power for pumps, cold rooms and processing.","sw":"Nishati ya jua na safi nyingine kwa pampu, vyumba baridi na usindikaji."}$j$::jsonb, $j${"en":"Size the system for your real daily load and plan for battery or panel replacement.","sw":"Pima ukubwa wa mfumo kulingana na mzigo wako halisi wa kila siku na upange kubadilisha betri au paneli."}$j$::jsonb, 12),
  ('marketplace-tech', 'cart', array['market-access']::text[], $j${"en":"Agricultural Marketplace Technology","sw":"Teknolojia ya Masoko ya Kilimo"}$j$::jsonb, $j${"en":"Platforms that connect sellers, buyers and price information.","sw":"Majukwaa yanayounganisha wauzaji, wanunuzi na taarifa za bei."}$j$::jsonb, $j${"en":"Check fees, payment methods and how disputes are handled before listing produce.","sw":"Angalia ada, njia za malipo na jinsi migogoro inavyoshughulikiwa kabla ya kuorodhesha mazao."}$j$::jsonb, 13)
