  ('china', 'a', $j${"en":"China","sw":"China"}$j$::jsonb, $j${"en":"Sample listing: drones, smart farm platforms and large-scale automation.","sw":"Orodha ya mfano: ndege zisizo na rubani, majukwaa ya mashamba janja na uendeshaji wa kiotomatiki."}$j$::jsonb, 0),
  ('russia', 'b', $j${"en":"Russia","sw":"Urusi"}$j$::jsonb, $j${"en":"Sample listing: large-field grain production and heavy mechanization.","sw":"Orodha ya mfano: uzalishaji wa nafaka kwenye mashamba makubwa na matumizi ya mashine nzito."}$j$::jsonb, 1),
  ('israel', 'c', $j${"en":"Israel","sw":"Israeli"}$j$::jsonb, $j${"en":"Sample listing: water-efficient irrigation and arid-land farming methods.","sw":"Orodha ya mfano: umwagiliaji unaotumia maji kwa ufanisi na mbinu za kilimo cha maeneo kame."}$j$::jsonb, 2),
  ('netherlands', 'd', $j${"en":"Netherlands","sw":"Uholanzi"}$j$::jsonb, $j${"en":"Sample listing: greenhouse horticulture and precision growing systems.","sw":"Orodha ya mfano: kilimo cha bustani ndani ya nyumba kitalu na mifumo ya uzalishaji sahihi."}$j$::jsonb, 3),
  ('india', 'e', $j${"en":"India","sw":"India"}$j$::jsonb, $j${"en":"Sample listing: phone-based advisory and low-cost tools for smallholders.","sw":"Orodha ya mfano: ushauri kupitia simu na zana za gharama nafuu kwa wakulima wadogo."}$j$::jsonb, 4),
  ('africa', 'f', $j${"en":"Africa","sw":"Afrika"}$j$::jsonb, $j${"en":"Sample listing: home-grown tools, from mobile advisory to solar cold storage.","sw":"Orodha ya mfano: zana za nyumbani, kuanzia ushauri wa simu hadi hifadhi baridi ya jua."}$j$::jsonb, 5),
  ('other-regions', 'g', $j${"en":"Other Regions","sw":"Kanda Nyingine"}$j$::jsonb, $j${"en":"Sample listing: ideas from the Americas, Europe, Oceania and beyond.","sw":"Orodha ya mfano: mawazo kutoka Amerika, Ulaya, Oceania na kwingineko."}$j$::jsonb, 6)
insert into public.innovations (slug, status, is_sample, sector, country_id, category_id, application_ids, title, summary, benefits, considerations, added_on) values
  ('solar-drip-kit', 'published', true, 'crop', 'israel', 'smart-irrigation', array['water-saving','energy-access']::text[], $j${"en":"Solar-powered drip irrigation kit","sw":"Kifaa cha umwagiliaji wa matone kinachotumia jua"}$j$::jsonb, $j${"en":"A sample listing for a small drip system that runs from a solar pump and a simple timer.","sw":"Orodha ya mfano ya mfumo mdogo wa matone unaotumia pampu ya jua na kipima muda rahisi."}$j$::jsonb, $j${"en":["Uses less water per plant","No fuel or grid power needed"],"sw":["Hutumia maji kidogo kwa kila mmea","Hauhitaji mafuta wala umeme wa gridi"]}$j$::jsonb, $j${"en":["Needs a clean water source to avoid blocked emitters","Spare parts and a trained installer should be nearby"],"sw":["Unahitaji chanzo safi cha maji ili kuepuka kuziba kwa matone","Vipuri na fundi aliyefunzwa wanapaswa kuwa karibu"]}$j$::jsonb, '2026-09-02'),
  ('scouting-drone', 'published', true, 'crop', 'china', 'agricultural-drones', array['crop-monitoring','pest-disease']::text[], $j${"en":"Crop-scouting survey drone","sw":"Ndege ya uchunguzi wa mazao"}$j$::jsonb, $j${"en":"A sample listing for a drone that photographs fields so patches of stress show up early.","sw":"Orodha ya mfano ya ndege inayopiga picha mashamba ili maeneo yenye changamoto yaonekane mapema."}$j$::jsonb, $j${"en":["Spots problems before they spread","Covers large plots quickly"],"sw":["Hugundua matatizo kabla hayajaenea","Hufunika mashamba makubwa kwa haraka"]}$j$::jsonb, $j${"en":["Drone rules and permits differ by country","Someone must learn to read the images"],"sw":["Sheria na vibali vya ndege hutofautiana kwa nchi","Mtu lazima ajifunze kusoma picha"]}$j$::jsonb, '2026-08-21'),
  ('greenhouse-sensor-grid', 'published', true, 'crop', 'netherlands', 'greenhouse', array['climate-control','crop-monitoring']::text[], $j${"en":"Greenhouse climate sensor grid","sw":"Mtandao wa vitambuzi vya hali ya hewa ya nyumba kitalu"}$j$::jsonb, $j${"en":"A sample listing for sensors that track heat, humidity and light inside a greenhouse.","sw":"Orodha ya mfano ya vitambuzi vinavyofuatilia joto, unyevu na mwanga ndani ya nyumba kitalu."}$j$::jsonb, $j${"en":["Steadier growing conditions","Alerts when conditions drift"],"sw":["Mazingira thabiti ya ukuzaji","Arifa hali inapobadilika"]}$j$::jsonb, $j${"en":["Sensors need regular calibration","Works best with a reliable power supply"],"sw":["Vitambuzi vinahitaji kurekebishwa mara kwa mara","Hufanya kazi vizuri zaidi na umeme wa uhakika"]}$j$::jsonb, '2026-08-10'),
  ('cattle-ear-tags', 'published', true, 'livestock', 'other-regions', 'livestock-technology', array['herd-health','farm-planning']::text[], $j${"en":"Smart ear tags for cattle","sw":"Vitambulisho janja vya masikio kwa ng’ombe"}$j$::jsonb, $j${"en":"A sample listing for tags that record movement and flag animals that may be unwell.","sw":"Orodha ya mfano ya vitambulisho vinavyorekodi mwenendo na kuonyesha wanyama wanaoweza kuwa wagonjwa."}$j$::jsonb, $j${"en":["Earlier sign of illness","Less time spent searching for animals"],"sw":["Dalili za ugonjwa mapema","Muda mdogo wa kutafuta wanyama"]}$j$::jsonb, $j${"en":["Needs a gateway with mobile or radio coverage","Tag cost per animal should be compared with herd value"],"sw":["Inahitaji kifaa cha mawasiliano chenye mtandao wa simu au redio","Gharama ya kitambulisho kwa mnyama ilinganishwe na thamani ya kundi"]}$j$::jsonb, '2026-09-15'),
  ('sms-crop-advisory', 'published', true, 'crop', 'africa', 'farm-software', array['farm-planning','pest-disease']::text[], $j${"en":"SMS crop advisory service","sw":"Huduma ya ushauri wa mazao kwa SMS"}$j$::jsonb, $j${"en":"A sample listing for a service that sends planting and pest advice to basic phones.","sw":"Orodha ya mfano ya huduma inayotuma ushauri wa upandaji na wadudu kwenye simu za kawaida."}$j$::jsonb, $j${"en":["Works on any phone","Advice arrives at the right time of season"],"sw":["Inafanya kazi kwenye simu yoyote","Ushauri hufika wakati sahihi wa msimu"]}$j$::jsonb, $j${"en":["Advice must be written in local languages","Message costs should be clear to farmers"],"sw":["Ushauri uandikwe kwa lugha za wenyeji","Gharama za ujumbe ziwe wazi kwa wakulima"]}$j$::jsonb, '2026-07-30'),
  ('soil-test-reader', 'published', true, 'crop', 'india', 'soil-health', array['soil-fertility']::text[], $j${"en":"Low-cost soil nutrient reader","sw":"Kifaa cha gharama nafuu cha kupima virutubisho vya udongo"}$j$::jsonb, $j${"en":"A sample listing for a handheld reader that estimates soil nutrients and suggests fertilizer amounts.","sw":"Orodha ya mfano ya kifaa cha mkononi kinachokadiria virutubisho vya udongo na kupendekeza kiasi cha mbolea."}$j$::jsonb, $j${"en":["Avoids over-fertilizing","Results in minutes, not weeks"],"sw":["Huepusha matumizi ya mbolea kupita kiasi","Matokeo ndani ya dakika, si wiki"]}$j$::jsonb, $j${"en":["Compare readings with a laboratory test at first","Soil types vary, so local calibration helps"],"sw":["Linganisha vipimo na maabara mwanzoni","Aina za udongo hutofautiana, hivyo kurekebisha kienyeji husaidia"]}$j$::jsonb, '2026-08-05'),
  ('poultry-climate-controller', 'published', true, 'livestock', 'china', 'livestock-technology', array['climate-control','herd-health']::text[], $j${"en":"Poultry house climate controller","sw":"Kidhibiti cha hali ya hewa ya banda la kuku"}$j$::jsonb, $j${"en":"A sample listing for a controller that adjusts fans and heaters to keep a poultry house comfortable.","sw":"Orodha ya mfano ya kidhibiti kinachorekebisha feni na hita ili banda la kuku liwe na hali nzuri."}$j$::jsonb, $j${"en":["Fewer heat-stress losses","Lower energy use"],"sw":["Hasara chache za mkazo wa joto","Matumizi madogo ya nishati"]}$j$::jsonb, $j${"en":["Needs a backup plan for power cuts","House design affects how well it works"],"sw":["Inahitaji mpango mbadala umeme ukikatika","Muundo wa banda huathiri utendaji wake"]}$j$::jsonb, '2026-07-18'),
  ('solar-cold-room', 'published', true, 'crop', 'africa', 'renewable-energy', array['post-harvest','energy-access']::text[], $j${"en":"Solar cold storage room","sw":"Chumba cha hifadhi baridi kinachotumia jua"}$j$::jsonb, $j${"en":"A sample listing for a cold room that keeps fruit and vegetables fresh using solar power.","sw":"Orodha ya mfano ya chumba baridi kinachotunza matunda na mboga mbichi kwa nguvu ya jua."}$j$::jsonb, $j${"en":["Less spoilage after harvest","More time to reach better markets"],"sw":["Uharibifu mdogo baada ya mavuno","Muda zaidi wa kufikia masoko bora"]}$j$::jsonb, $j${"en":["Shared use by a group can lower the cost per farmer","Roads to markets still matter"],"sw":["Matumizi ya pamoja ya kikundi hupunguza gharama kwa mkulima","Barabara za kwenda sokoni bado ni muhimu"]}$j$::jsonb, '2026-09-09'),
  ('gps-guided-planter', 'published', true, 'crop', 'russia', 'precision-agriculture', array['crop-monitoring','farm-planning']::text[], $j${"en":"GPS-guided planter attachment","sw":"Kifaa cha kupandia kinachoongozwa na GPS"}$j$::jsonb, $j${"en":"A sample listing for a tractor attachment that plants seed in straight, evenly spaced rows.","sw":"Orodha ya mfano ya kifaa cha trekta kinachopanda mbegu kwa mistari iliyonyooka na nafasi sawa."}$j$::jsonb, $j${"en":["Even plant spacing","Less wasted seed"],"sw":["Nafasi sawa za mimea","Mbegu chache zinazopotea"]}$j$::jsonb, $j${"en":["Best suited to larger, flatter fields","Needs a tractor and trained operator"],"sw":["Inafaa zaidi mashamba makubwa na tambarare","Inahitaji trekta na mwendeshaji aliyefunzwa"]}$j$::jsonb, '2026-06-25'),
  ('yield-forecast-model', 'published', true, 'crop', 'india', 'ai-in-agriculture', array['farm-planning','crop-monitoring']::text[], $j${"en":"Yield forecast assistant","sw":"Msaidizi wa kukadiria mavuno"}$j$::jsonb, $j${"en":"A sample listing for a tool that uses weather and field records to estimate the coming harvest.","sw":"Orodha ya mfano ya zana inayotumia hali ya hewa na kumbukumbu za shamba kukadiria mavuno yajayo."}$j$::jsonb, $j${"en":["Helps plan labour and storage","Shows which fields need attention"],"sw":["Husaidia kupanga vibarua na uhifadhi","Huonyesha mashamba yanayohitaji uangalizi"]}$j$::jsonb, $j${"en":["Estimates are only as good as the records fed in","Forecasts are guides, not guarantees"],"sw":["Makadirio ni mazuri kama kumbukumbu zilizoingizwa","Makadirio ni mwongozo, si hakikisho"]}$j$::jsonb, '2026-09-28'),
  ('weeding-robot', 'published', true, 'crop', 'netherlands', 'agricultural-robotics', array['pest-disease','crop-monitoring']::text[], $j${"en":"Row-crop weeding robot","sw":"Roboti ya kupalilia mazao ya mistari"}$j$::jsonb, $j${"en":"A sample listing for a small robot that identifies and removes weeds between crop rows.","sw":"Orodha ya mfano ya roboti ndogo inayotambua na kuondoa magugu kati ya mistari ya mazao."}$j$::jsonb, $j${"en":["Less hand weeding labour","Fewer herbicides needed"],"sw":["Kazi ndogo ya kupalilia kwa mkono","Dawa chache za kuua magugu"]}$j$::jsonb, $j${"en":["High purchase cost suits shared ownership","Works best on well-spaced rows"],"sw":["Gharama kubwa ya ununuzi inafaa umiliki wa pamoja","Hufanya kazi vizuri kwenye mistari yenye nafasi nzuri"]}$j$::jsonb, '2026-05-14'),
  ('pest-trap-sensor', 'published', true, 'crop', 'israel', 'crop-protection', array['pest-disease','crop-monitoring']::text[], $j${"en":"Connected pest trap counter","sw":"Kihesabu cha mtego wa wadudu kilichounganishwa"}$j$::jsonb, $j${"en":"A sample listing for a trap that counts insects and sends the numbers to a phone.","sw":"Orodha ya mfano ya mtego unaohesabu wadudu na kutuma namba kwenye simu."}$j$::jsonb, $j${"en":["Spray only when numbers rise","Early warning of outbreaks"],"sw":["Nyunyizia tu idadi inapopanda","Onyo la mapema la milipuko"]}$j$::jsonb, $j${"en":["Traps cover a limited area","Needs regular cleaning and lure replacement"],"sw":["Mitego hufunika eneo dogo","Inahitaji kusafishwa na kubadilisha chambo mara kwa mara"]}$j$::jsonb, '2026-07-04'),
  ('farm-sensor-starter-kit', 'published', true, 'crop', 'china', 'smart-farming', array['water-saving','crop-monitoring','farm-planning']::text[], $j${"en":"Smart farm sensor starter kit","sw":"Seti ya vitambuzi vya shamba janja ya kuanzia"}$j$::jsonb, $j${"en":"A sample listing for a starter set of soil, weather and water sensors with one phone app.","sw":"Orodha ya mfano ya seti ya kuanzia ya vitambuzi vya udongo, hali ya hewa na maji yenye programu moja ya simu."}$j$::jsonb, $j${"en":["One view of the whole farm","Easy to start small and add sensors"],"sw":["Mtazamo mmoja wa shamba zima","Rahisi kuanza kidogo na kuongeza vitambuzi"]}$j$::jsonb, $j${"en":["Check which sensors work without internet","Plan who will maintain the devices"],"sw":["Angalia vitambuzi vinavyofanya kazi bila intaneti","Panga nani atatunza vifaa"]}$j$::jsonb, '2026-06-10'),
  ('mobile-grain-dryer', 'published', true, 'crop', 'russia', 'processing', array['post-harvest','energy-access']::text[], $j${"en":"Mobile grain dryer","sw":"Kikaushio cha nafaka kinachohamishika"}$j$::jsonb, $j${"en":"A sample listing for a movable dryer that lowers grain moisture before storage.","sw":"Orodha ya mfano ya kikaushio kinachohamishika kinachopunguza unyevu wa nafaka kabla ya kuhifadhi."}$j$::jsonb, $j${"en":["Lower risk of mould in storage","Can serve several farms in turn"],"sw":["Hatari ndogo ya ukungu wakati wa kuhifadhi","Kinaweza kuhudumia mashamba kadhaa kwa zamu"]}$j$::jsonb, $j${"en":["Fuel or power source must be planned","Scheduling across farms needs coordination"],"sw":["Chanzo cha mafuta au umeme lazima kipangwe","Ratiba kati ya mashamba inahitaji uratibu"]}$j$::jsonb, '2026-05-30'),
  ('farm-market-app', 'published', true, 'crop', 'africa', 'marketplace-tech', array['market-access','farm-planning']::text[], $j${"en":"Farm produce marketplace app","sw":"Programu ya soko la mazao ya shamba"}$j$::jsonb, $j${"en":"A sample listing for an app that connects farmers with buyers and shows current prices.","sw":"Orodha ya mfano ya programu inayounganisha wakulima na wanunuzi na kuonyesha bei za sasa."}$j$::jsonb, $j${"en":["Wider choice of buyers","Price information before selling"],"sw":["Chaguo pana la wanunuzi","Taarifa za bei kabla ya kuuza"]}$j$::jsonb, $j${"en":["Needs a trusted way to handle payments","Delivery and quality checks must be agreed"],"sw":["Inahitaji njia ya kuaminika ya malipo","Usafirishaji na ukaguzi wa ubora lazima vikubaliwe"]}$j$::jsonb, '2026-09-20'),
  ('milking-quality-monitor', 'published', true, 'livestock', 'netherlands', 'livestock-technology', array['herd-health','farm-planning']::text[], $j${"en":"Milking and milk-quality monitor","sw":"Kifuatiliaji cha ukamuaji na ubora wa maziwa"}$j$::jsonb, $j${"en":"A sample listing for equipment that records each cow’s milk yield and flags quality changes.","sw":"Orodha ya mfano ya vifaa vinavyorekodi maziwa ya kila ng’ombe na kuonyesha mabadiliko ya ubora."}$j$::jsonb, $j${"en":["Spots udder problems early","Better records per cow"],"sw":["Hugundua matatizo ya kiwele mapema","Kumbukumbu bora kwa kila ng’ombe"]}$j$::jsonb, $j${"en":["Suits farms with a regular milking routine","Cleaning and calibration schedule needed"],"sw":["Inafaa mashamba yenye ratiba ya kukamua","Ratiba ya usafi na kurekebisha inahitajika"]}$j$::jsonb, '2026-08-28'),
  ('feed-ration-planner', 'published', true, 'livestock', 'other-regions', 'farm-software', array['farm-planning','herd-health']::text[], $j${"en":"Feed ration planner","sw":"Mpangaji wa mgao wa malisho"}$j$::jsonb, $j${"en":"A sample listing for software that suggests feed mixes from local ingredients and animal needs.","sw":"Orodha ya mfano ya programu inayopendekeza mchanganyiko wa malisho kutoka viungo vya kienyeji na mahitaji ya wanyama."}$j$::jsonb, $j${"en":["Lower feed cost per animal","Balanced nutrition"],"sw":["Gharama ndogo ya malisho kwa mnyama","Lishe iliyosawazika"]}$j$::jsonb, $j${"en":["Needs local feed prices and nutrient values","Advice should be checked with an animal nutritionist"],"sw":["Inahitaji bei za malisho ya kienyeji na viwango vya virutubisho","Ushauri uhakikiwe na mtaalamu wa lishe ya wanyama"]}$j$::jsonb, '2026-06-01')
insert into public.articles (slug, status, is_sample, type, sector, category_ids, title, summary, body, minutes, published_on) values
  ('k1', 'published', true, 'summary', 'crop', array['smart-irrigation']::text[], $j${"en":"What recent studies say about drip irrigation and yield","sw":"Tafiti za hivi karibuni zinasema nini kuhusu umwagiliaji wa matone na mavuno"}$j$::jsonb, $j${"en":"Sample summary of how water-saving systems affect harvests.","sw":"Muhtasari wa mfano wa jinsi mifumo ya kuokoa maji inavyoathiri mavuno."}$j$::jsonb, $j${"en":["This is a demonstration summary. It shows how a research summary page will look, and it does not report real findings.","A real entry would state the study question, the method, the main result and its limits, then link to the original source."],"sw":["Huu ni muhtasari wa mfano. Unaonyesha jinsi ukurasa wa muhtasari wa utafiti utakavyoonekana, na hauripoti matokeo halisi.","Kipengee halisi kingeeleza swali la utafiti, mbinu, matokeo makuu na mipaka yake, kisha kuunganisha na chanzo asili."]}$j$::jsonb, 4, '2026-09-12'),
  ('k2', 'published', true, 'caseStudy', 'crop', array['renewable-energy','processing']::text[], $j${"en":"A smallholder group adopts solar cold storage","sw":"Kikundi cha wakulima wadogo kinapokea hifadhi baridi ya jua"}$j$::jsonb, $j${"en":"Sample case study about reducing post-harvest losses.","sw":"Utafiti wa kesi wa mfano kuhusu kupunguza hasara baada ya mavuno."}$j$::jsonb, $j${"en":["This is an invented example, not a real group or result. It shows the layout for case studies.","A real case study would describe the starting problem, what was installed, what changed and what the group would do differently."],"sw":["Huu ni mfano uliobuniwa, si kikundi au matokeo halisi. Unaonyesha mpangilio wa tafiti za kesi.","Utafiti halisi wa kesi ungeeleza tatizo la mwanzo, kilichowekwa, kilichobadilika na ambacho kikundi kingefanya tofauti."]}$j$::jsonb, 6, '2026-08-30'),
  ('k3', 'published', true, 'cropGuide', 'crop', array['soil-health']::text[], $j${"en":"A practical guide to soil testing before planting","sw":"Mwongozo wa vitendo wa kupima udongo kabla ya kupanda"}$j$::jsonb, $j${"en":"Sample guide on taking soil samples and reading results.","sw":"Mwongozo wa mfano wa kuchukua sampuli za udongo na kusoma matokeo."}$j$::jsonb, $j${"en":["This sample guide shows how step-by-step farming guides will be laid out. The advice is general and should be checked with a local extension officer.","Typical sections: when to sample, how many spots to sample, how to label bags, and how to use the results when choosing inputs."],"sw":["Mwongozo huu wa mfano unaonyesha jinsi miongozo ya kilimo ya hatua kwa hatua itakavyopangwa. Ushauri ni wa jumla na unapaswa kuhakikiwa na afisa ugani wa eneo lako.","Sehemu za kawaida: lini kuchukua sampuli, maeneo mangapi, jinsi ya kuweka lebo kwenye mifuko, na kutumia matokeo kuchagua pembejeo."]}$j$::jsonb, 8, '2026-09-01'),
  ('k4', 'published', true, 'livestockGuide', 'livestock', array['livestock-technology']::text[], $j${"en":"Keeping dairy cows healthy through the dry season","sw":"Kuweka ng’ombe wa maziwa wenye afya wakati wa kiangazi"}$j$::jsonb, $j${"en":"Sample guide on feeding, water and shade.","sw":"Mwongozo wa mfano kuhusu malisho, maji na kivuli."}$j$::jsonb, $j${"en":["This is a demonstration guide. Animal health advice should always be confirmed with a qualified veterinarian.","A real guide would cover feed budgeting, clean water access, shade and signs that an animal needs a vet."],"sw":["Huu ni mwongozo wa mfano. Ushauri wa afya ya wanyama lazima uthibitishwe na daktari wa mifugo aliyehitimu.","Mwongozo halisi ungehusu bajeti ya malisho, upatikanaji wa maji safi, kivuli na dalili kwamba mnyama anahitaji daktari."]}$j$::jsonb, 10, '2026-09-18'),
  ('k5', 'published', true, 'climate', 'both', array['smart-farming','smart-irrigation']::text[], $j${"en":"Planning crops around uneven rainfall","sw":"Kupanga mazao kulingana na mvua zisizo za uhakika"}$j$::jsonb, $j${"en":"Sample overview of climate-smart planting choices.","sw":"Muhtasari wa mfano wa uchaguzi wa upandaji unaostahimili tabianchi."}$j$::jsonb, $j${"en":["This is a sample overview. It shows how climate-smart agriculture topics will be presented.","A real article would compare crop and variety choices, planting dates, water storage and soil cover, with local data."],"sw":["Huu ni muhtasari wa mfano. Unaonyesha jinsi mada za kilimo kinachostahimili tabianchi zitakavyowasilishwa.","Makala halisi ingelinganisha mazao na aina, tarehe za kupanda, uhifadhi wa maji na kufunika udongo, kwa data za eneo."]}$j$::jsonb, 4, '2026-08-15'),
  ('k6', 'published', true, 'implementation', 'both', array['farm-software']::text[], $j${"en":"Rolling out a farm record app across a cooperative","sw":"Kuanzisha programu ya kumbukumbu za shamba katika chama cha ushirika"}$j$::jsonb, $j${"en":"Sample walkthrough of training, devices and follow-up.","sw":"Mfano wa hatua za mafunzo, vifaa na ufuatiliaji."}$j$::jsonb, $j${"en":["This is a made-up implementation example for layout purposes. No real cooperative is described.","A real example would list the steps taken, the time and cost involved, the problems met and the lessons learned."],"sw":["Huu ni mfano wa utekelezaji uliobuniwa kwa ajili ya mpangilio. Hakuna chama halisi kinachoelezwa.","Mfano halisi ungeorodhesha hatua zilizochukuliwa, muda na gharama, matatizo yaliyojitokeza na mafunzo yaliyopatikana."]}$j$::jsonb, 6, '2026-07-22'),
  ('k7', 'published', true, 'livestockGuide', 'livestock', array['livestock-technology']::text[], $j${"en":"Poultry house ventilation basics","sw":"Misingi ya uingizaji hewa katika banda la kuku"}$j$::jsonb, $j${"en":"Sample guide to airflow, heat and chick comfort.","sw":"Mwongozo wa mfano kuhusu mzunguko wa hewa, joto na starehe ya vifaranga."}$j$::jsonb, $j${"en":["This is a demonstration guide and not a verified recommendation. Ask a poultry specialist before changing a house.","A real guide would explain airflow, heat, humidity and how to read bird behaviour as a signal."],"sw":["Huu ni mwongozo wa mfano na si pendekezo lililohakikiwa. Muulize mtaalamu wa kuku kabla ya kubadilisha banda.","Mwongozo halisi ungeeleza mzunguko wa hewa, joto, unyevu na jinsi ya kusoma tabia ya ndege kama ishara."]}$j$::jsonb, 8, '2026-06-28'),
  ('k8', 'published', true, 'summary', 'crop', array['agricultural-drones','crop-protection']::text[], $j${"en":"Drone imagery for early pest detection: a review","sw":"Picha za ndege zisizo na rubani kugundua wadudu mapema: mapitio"}$j$::jsonb, $j${"en":"Sample review of how aerial images flag crop stress.","sw":"Mapitio ya mfano ya jinsi picha za angani zinavyoonyesha mazao yenye changamoto."}$j$::jsonb, $j${"en":["This is a sample review page, not a real literature review.","A real review would list the studies included, how they were chosen, what they agree on and where evidence is thin."],"sw":["Huu ni ukurasa wa mfano wa mapitio, si mapitio halisi ya machapisho.","Mapitio halisi yangeorodhesha tafiti zilizojumuishwa, jinsi zilivyochaguliwa, wanachokubaliana na pale ushahidi ni mdogo."]}$j$::jsonb, 10, '2026-09-25')
